{
  "items": [
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "norm_sum_le_of_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedAddCommGroup E] (s : Finset ι) {f : ι → E} {n : ι → ℝ},\n  (∀ b ∈ s, ‖f b‖ ≤ n b) → ‖∑ b ∈ s, f b‖ ≤ ∑ b ∈ s, n b"
    },
    {
      "name": "LaurentSeries.hasseDeriv",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "definition",
      "type": "(R : Type u_2) →\n  {V : Type u_3} →\n    [inst : AddCommGroup V] → [inst_1 : Semiring R] → [inst_2 : Module R V] → ℕ → LaurentSeries V →ₗ[R] LaurentSeries V"
    },
    {
      "name": "Polynomial.hasseDeriv_apply",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f : Polynomial R),\n  (Polynomial.hasseDeriv k) f = f.sum fun i r => (Polynomial.monomial (i - k)) (↑(i.choose k) * r)"
    },
    {
      "name": "nnnorm_prod_le_of_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedCommGroup E] (s : Finset ι) {f : ι → E} {n : ι → NNReal},\n  (∀ b ∈ s, ‖f b‖₊ ≤ n b) → ‖∏ b ∈ s, f b‖₊ ≤ ∑ b ∈ s, n b"
    },
    {
      "name": "LaurentSeries.hasseDeriv_single",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {V : Type u_2} [inst_1 : AddCommGroup V] [inst_2 : Module R V] (k : ℕ) (n : ℤ)\n  (x : V), (LaurentSeries.hasseDeriv R k) ((HahnSeries.single n) x) = (HahnSeries.single (n - ↑k)) (Ring.choose n k • x)"
    },
    {
      "name": "Polynomial.hasseDeriv_monomial",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k n : ℕ) (r : R),\n  (Polynomial.hasseDeriv k) ((Polynomial.monomial n) r) = (Polynomial.monomial (n - k)) (↑(n.choose k) * r)"
    },
    {
      "name": "LaurentSeries.hasseDeriv_single_add",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {V : Type u_2} [inst_1 : AddCommGroup V] [inst_2 : Module R V] (k : ℕ) (n : ℤ)\n  (x : V),\n  (LaurentSeries.hasseDeriv R k) ((HahnSeries.single (n + ↑k)) x) = (HahnSeries.single n) (Ring.choose (n + ↑k) k • x)"
    }
  ]
}
